SCU.courseByCode = function (code) {
  code = String(code || '').trim().toUpperCase();
  return SCU.COURSES.find(function (c) { return String(c.code).toUpperCase() === code; }) || null;
};
SCU.slotText = function (c) {
  return c.slots.map(function (s) {
    var a = (SCU.PERIODS[s.start - 1] || {}).label || s.start;
    var b = (SCU.PERIODS[s.end - 1] || {}).label || s.end;
    return '週' + SCU.DAYS[s.day] + ' ' + a + (b !== a ? '–' + b : '') + '節';
  }).join('、');
};
